        result = search_distance(load_distances(data_dir), a.origin or "", a.destination or "", a.mode)
    elif a.kind == "accommodations":
        result = by_city(load_accommodations(data_dir), a.city or "", "city") or \
            "There are no accommodations in this city."
    elif a.kind == "restaurants":
        result = by_city(load_restaurants(data_dir), a.city or "", "City") or \
            "There is no restaurant in this city."
    else:
        result = by_city(load_attractions(data_dir), a.city or "", "City") or \
            "There is no attraction in this city."
    print(json.dumps(result, ensure_ascii=False, indent=1))


if __name__ == "__main__":
    _main()

tool_use_result.content:
"""Stdlib-only loaders and lookups over the TravelPlanner-style sandbox datasets.

Mirrors the six curated search skills (search-cities, search-flights,
search-driving-distance, search-accommodations, search-restaurants,
search-attractions) with the same filtering semantics, so whatever these
functions return is exactly what the sandbox "contains":

- rows missing any selected column are dropped (pandas ``dropna`` semantics,
  including pandas' default NA strings such as "", "NA", "None", "nan");
- city/state lookups strip text after the first "(";
- flights match origin, destination and date exactly (case-sensitive);
- driving distance matches origin/destination exactly; a duration containing
  "day" means "no valid information"; cost is int(km * 0.05) for self-driving
  and int(km) for taxi (per vehicle);
- accommodations/restaurants/attractions match city case-insensitively.

Also usable as a CLI for ad-hoc lookups, printing JSON:

    python travel_db.py cities --state Texas
    python travel_db.py flights --origin "New York" --destination Denver --date 2022-03-16
    python travel_db.py distance --origin Killeen --destination Austin --mode self-driving
    python travel_db.py accommodations --city Austin
    python travel_db.py restaurants --city Austin
    python travel_db.py attractions --city Austin
    (add --data-dir DIR when the data folder is not auto-discovered)
"""

from __future__ import annotations

import argparse
import csv
import json
import os
import sys
from pathlib import Path

MARKER = Path("background") / "citySet_with_states.txt"

FILES = {
    "cities": Path("background") / "citySet_with_states.txt",
    "flights": Path("flights") / "clean_Flights_2022.csv",
    "distance": Path("googleDistanceMatrix") / "distance.csv",
    "accommodations": Path("accommodations") / "clean_accommodations_2022.csv",
    "restaurants": Path("restaurants") / "clean_restaurant_2022.csv",
    "attractions": Path("attractions") / "attractions.csv",
}

FLIGHT_COLUMNS = ["Flight Number", "Price", "DepTime", "ArrTime", "ActualElapsedTime",
                  "FlightDate", "OriginCityName", "DestCityName", "Distance"]
DISTANCE_COLUMNS = ["origin", "destination", "duration", "distance"]
ACCOMMODATION_COLUMNS = ["NAME", "price", "room type", "house_rules", "minimum nights",
                         "maximum occupancy", "review rate number", "city"]
RESTAURANT_COLUMNS = ["Name", "Average Cost", "Cuisines", "Aggregate Rating", "City"]
ATTRACTION_COLUMNS = ["Name", "Latitude", "Longitude", "Address", "Phone", "Website", "City"]

# pandas.read_csv default NA strings: such cells count as missing and drop the row.
NA_STRINGS = {"", "#N/A", "#N/A N/A", "#NA", "-1.#IND", "-1.#QNAN", "-NaN", "-nan",
              "1.#IND", "1.#QNAN", "<NA>", "N/A", "NA", "NULL", "NaN", "None", "n/a",
              "nan", "null"}

csv.field_size_limit(sys.maxsize)


def before_paren(value: str | None) -> str:
    """Return the substring before the first '(' (e.g. 'Austin(Texas)' -> 'Austin')."""
    if value is None:
        return ""
    return str(value).split("(", 1)[0].strip()


# ---------------------------------------------------------------- data dir ---

def _candidate_dirs(explicit: str | None) -> list[Path]:
    out: list[Path] = []
    if explicit:
        out.append(Path(explicit).expanduser())
    env = os.environ.get("TRAVEL_DATA_DIR")
    if env:
        out.append(Path(env).expanduser())
    here = Path(__file__).resolve().parent
    out += [Path("/app/data"), Path("/root/data"), Path("/root/environment/data"),
            Path("/root"), Path("/data"), Path("/workspace/data"), Path.cwd() / "data",
            here.parent / "data", here.parent.parent / "data"]
    return out


def find_data_dir(explicit: str | None = None) -> Path:
    """Locate the folder holding background/, flights/, googleDistanceMatrix/, ...

    Order: explicit argument, $TRAVEL_DATA_DIR, common container paths, then a
    shallow search (depth <= 4) under /app, /root, /data, /workspace, /mnt, /home.
    """
    for cand in _candidate_dirs(explicit):
        if (cand / MARKER).is_file():
            return cand
    if explicit and Path(explicit).is_dir():
        # Explicit folder that holds the files somewhere below it.
        roots = [Path(explicit)]
    else:
        roots = [Path(p) for p in ("/app", "/root", "/data", "/workspace", "/mnt", "/home")]
    for root in roots:
        if not root.is_dir():
            continue
        base_depth = len(root.parts)
        for dirpath, dirnames, _ in os.walk(root):
            depth = len(Path(dirpath).parts) - base_depth
            if depth >= 4:
                dirnames[:] = []
            dirnames[:] = [d for d in dirnames if not d.startswith(".") and d not in
                           ("proc", "sys", "node_modules", "site-packages", "__pycache__")]
            if (Path(dirpath) / MARKER).is_file():
                return Path(dirpath)
    raise FileNotFoundError(
        "Travel data folder not found (looked for background/citySet_with_states.txt). "
        "Pass data_dir / --data-dir or set TRAVEL_DATA_DIR.")


# ------------------------------------------------------------------ loaders ---

def _rows(path: Path, columns: list[str], rename: dict[str, str] | None = None):
    """Yield dicts with only `columns`, skipping rows where any is NA (dropna)."""
    with path.open(newline="", encoding="utf-8") as fh:
        reader = csv.reader(fh)
        header = next(reader)
        if rename:
            header = [rename.get(h, h) for h in header]
        idx = {c: header.index(c) for c in columns if c in header}
        for raw in reader:
            row = {}
            ok = True
            for col, i in idx.items():
                v = raw[i] if i < len(raw) else ""
                if v in NA_STRINGS:
                    ok = False
                    break
                row[col] = v
            if ok:
                yield row


def _num(value: str) -> float:
    return float(str(value).replace(",", ""))


def load_city_states(data_dir: Path) -> dict[str, list[str]]:
    """State -> cities, from the tab-separated city<TAB>state file."""
    mapping: dict[str, list[str]] = {}
    text = (data_dir / FILES["cities"]).read_text(encoding="utf-8").strip()
    for line in text.splitlines():
        if not line.strip():
            continue
        city, sep, state = line.partition("\t")
        if not sep:
            continue
        city, state = city.strip(), state.strip()
        if city and state:
            mapping.setdefault(state, []).append(city)
    return mapping


def cities_for_state(mapping: dict[str, list[str]], state: str) -> list[str] | None:
    want = before_paren(state).lower()
    for key, cities in mapping.items():
        if key.lower() == want:
            return list(cities)
    return None


def state_of_city(mapping: dict[str, list[str]], city: str) -> str | None:
    want = before_paren(city).lower()
    for state, cities in mapping.items():
        if any(c.lower() == want for c in cities):
            return state
    return None


def load_flights(data_dir: Path, dates: set[str] | None = None,
                 cities: set[str] | None = None) -> list[dict]:
    """Flights, optionally restricted to FlightDate in `dates` and both ends in `cities`."""
    out = []
    for r in _rows(data_dir / FILES["flights"], FLIGHT_COLUMNS, {"Unnamed: 0": "Flight Number"}):
        if dates is not None and r["FlightDate"] not in dates:
            continue
        o, d = r["OriginCityName"], r["DestCityName"]
        if cities is not None and (o not in cities or d not in cities):
            continue
        r["Price"] = _num(r["Price"])
        out.append(r)
    return out


def search_flights(flights: list[dict], origin: str, destination: str, date: str) -> list[dict]:
    o, d = before_paren(origin), before_paren(destination)
    return [f for f in flights if f["OriginCityName"] == o and f["DestCityName"] == d
            and f["FlightDate"] == date]


def load_distances(data_dir: Path) -> dict[tuple[str, str], dict]:
    """(origin, destination) -> first matching row (the original tool takes values[0])."""
    out: dict[tuple[str, str], dict] = {}
    for r in _rows(data_dir / FILES["distance"], DISTANCE_COLUMNS):
        key = (r["origin"].strip(), r["destination"].strip())
        out.setdefault(key, r)
    return out


def parse_km(text: str) -> float | None:
    try:
        return float(str(text).lower().replace("km", "").replace(",", "").strip())
    except (TypeError, ValueError):
        return None


def mode_cost(distance_km: float | None, mode: str) -> int | None:
    """Per-vehicle cost: self-driving int(km*0.05), taxi int(km)."""
    if distance_km is None:
        return None
    mode = mode.lower()
    if "driving" in mode or "self-drive" in mode:
        return int(distance_km * 0.05)
    if mode == "taxi":
        return int(distance_km)
    return None


def search_distance(distances: dict, origin: str, destination: str, mode: str = "driving") -> dict:
    """Return {origin, destination, duration, distance, distance_km, cost, valid}."""
    o, d = before_paren(origin), before_paren(destination)
    info = {"origin": o, "destination": d, "mode": mode, "duration": None,
            "distance": None, "distance_km": None, "cost": None, "valid": False}
    row = distances.get((o, d))
    if not row:
        return info
    duration, dist = row["duration"], row["distance"]
    if "day" in duration.lower():
        return info
    km = parse_km(dist)
    info.update(duration=duration, distance=dist, distance_km=km,
                cost=mode_cost(km, mode), valid=True)
    return info


def load_accommodations(data_dir: Path) -> list[dict]:
    out = []
    for r in _rows(data_dir / FILES["accommodations"], ACCOMMODATION_COLUMNS):
        r["city"] = r["city"].strip()
        r["price"] = _num(r["price"])
        r["minimum nights"] = _num(r["minimum nights"])
        r["maximum occupancy"] = int(_num(r["maximum occupancy"]))
        r["review rate number"] = _num(r["review rate number"])
        out.append(r)
    return out


def load_restaurants(data_dir: Path) -> list[dict]:
    out = []
    for r in _rows(data_dir / FILES["restaurants"], RESTAURANT_COLUMNS):
        r["City"] = r["City"].strip()
        r["Average Cost"] = _num(r["Average Cost"])
        r["Aggregate Rating"] = _num(r["Aggregate Rating"])
        r["cuisine_list"] = [c.strip() for c in r["Cuisines"].split(",") if c.strip()]
        out.append(r)
    return out


def load_attractions(data_dir: Path) -> list[dict]:
    out = []
    for r in _rows(data_dir / FILES["attractions"], ATTRACTION_COLUMNS):
        r["City"] = r["City"].strip()
        out.append(r)
    return out


def by_city(rows: list[dict], city: str, key: str) -> list[dict]:
    want = before_paren(city).strip().lower()
    return [r for r in rows if r[key].lower() == want]


# ---------------------------------------------------------------------- CLI ---

def _main() -> None:
    p = argparse.ArgumentParser(description="Look up the travel sandbox datasets (JSON output).")
    p.add_argument("kind", choices=["cities", "flights", "distance", "accommodations",
                                    "restaurants", "attractions", "datadir"])
    p.add_argument("--state", "-s")
    p.add_argument("--city", "-c")
    p.add_argument("--origin", "-o")
    p.add_argument("--destination", "-d")
    p.add_argument("--date", "-t", help="YYYY-MM-DD")
    p.add_argument("--mode", "-m", default="self-driving", help="self-driving or taxi")
    p.add_argument("--data-dir")
    a = p.parse_args()
    data_dir = find_data_dir(a.data_dir)
    if a.kind == "datadir":
        result: object = str(data_dir)
    elif a.kind == "cities":
        result = cities_for_state(load_city_states(data_dir), a.state or "") or "Invalid state."
    elif a.kind == "flights":
        rows = load_flights(data_dir, {a.date} if a.date else None)
        result = search_flights(rows, a.origin or "", a.destination or "", a.date or "")
        if not result:
            result = f"There is no flight from {a.origin} to {a.destination} on {a.date}."
    elif a.kind == "distance":
        result = search_distance(load_distances(data_dir), a.origin or "", a.destination or "", a.mode)
    elif a.kind == "accommodations":
        result = by_city(load_accommodations(data_dir), a.city or "", "city") or \
            "There are no accommodations in this city."
    elif a.kind == "restaurants":
        result = by_city(load_restaurants(data_dir), a.city or "", "City") or \
            "There is no restaurant in this city."
    else:
        result = by_city(load_attractions(data_dir), a.city or "", "City") or \
            "There is no attraction in this city."
    print(json.dumps(result, ensure_ascii=False, indent=1))


if __name__ == "__main__":
    _main()

input.content:
"""AIP execution step: search the sandbox for the cheapest valid trip and draft a day-by-day plan.

stdin:  {"currentState": {...parsed query...}, "assets": {...}, "expects": [...]}
stdout: {"data_dir", "trip_dates", "candidate_cities", "draft_plan", "draft_cost",
         "cost_breakdown", "route", "alternatives", "candidates", "planner_notes", "feasible"}

The search enumerates every ordered choice of `visiting_city_number` cities from the
destination (a state's cities, or the single destination city), every split of the
trip's nights across them, and both transport regimes (flight+taxi, self-driving+taxi;
flights and self-driving never mix). Each option is costed with the evaluation rules:
flight price x people, self-driving cost x ceil(people/5), taxi cost x ceil(people/4),
accommodation price x ceil(people/maximum occupancy) per night, meals Average Cost x people.
"""

from __future__ import annotations

import itertools
import json
import math
import sys
from datetime import date, timedelta

import travel_db as db

MEALS = {"breakfast": 8 * 60, "lunch": 12 * 60 + 30, "dinner": 19 * 60}
GROUND_DEPART = 9 * 60  # assumed departure time for self-driving / taxi legs


# --------------------------------------------------------------- utilities ---

def fail(msg: str) -> None:
    print(json.dumps({"feasible": False, "planner_notes": [msg], "draft_plan": [],
                      "draft_cost": 0.0, "cost_breakdown": {}, "candidates": {},
                      "route": {}, "alternatives": [], "candidate_cities": [],
                      "trip_dates": [], "data_dir": ""}))
    sys.exit(0)


def hhmm(t: str) -> int | None:
    try:
        h, m = str(t).strip().split(":")[:2]
        return int(h) * 60 + int(m)
    except (ValueError, AttributeError):
        return None


def duration_minutes(text: str) -> int:
    """'2 hours 33 minutes' / '1 hour 1 min' / '45 mins' -> minutes."""
    total, num = 0, None
    for tok in str(text).replace(",", " ").split():
        if tok.replace(".", "", 1).isdigit():
            num = float(tok)
        elif num is not None:
            if tok.startswith("day"):
                total += num * 1440
            elif tok.startswith("hour"):
                total += num * 60
            elif tok.startswith("min"):
                total += num
            num = None
    return int(total)


def constraint(lc: dict, *keys: str):
    for k in keys:
        if k in lc and lc[k] not in (None, "", "-", [], "null", "None"):
            return lc[k]
    return None


def norm_list(v) -> list[str]:
    if v is None:
        return []
    if isinstance(v, str):
        return [s.strip() for s in v.replace(";", ",").split(",") if s.strip()]
    return [str(s).strip() for s in v if str(s).strip()]


def accommodation_ok(a: dict, room_type: str | None, house_rule: str | None) -> bool:
    if room_type:
        rt = room_type.strip().lower()
        t = a["room type"]
        if rt == "not shared room" and t == "Shared room":
            return False
        if rt == "shared room" and t != "Shared room":
            return False
        if rt == "private room" and t != "Private room":
            return False
        if rt in ("entire room", "entire home/apt", "entire home") and t != "Entire home/apt":
            return False
    for rule in norm_list(house_rule):
        if f"no {rule.lower()}" in a["house_rules"].lower():
            return False
    return True


def compositions(total: int, parts: int):
    """All ways to write `total` as an ordered sum of `parts` positive integers."""
    if parts == 1:
        if total >= 1:
            yield (total,)
        return
    for first in range(1, total - parts + 2):
        for rest in compositions(total - first, parts - 1):
            yield (first,) + rest


def name_city(name: str, city: str) -> str:
    return f"{name}, {city}"


# ------------------------------------------------------------------- main ---

def main() -> None:
    payload = json.load(sys.stdin)
    st = payload.get("currentState", payload)

    try:
        data_dir = db.find_data_dir(st.get("data_dir") or None)
    except FileNotFoundError as exc:
        fail(str(exc))

    origin = db.before_paren(st["origin"])
    destination = db.before_paren(st["destination"])
    days = int(st["days"])
    n_cities = max(1, int(st.get("visiting_city_number") or 1))
    people = max(1, int(st.get("people_number") or 1))
    budget = float(st.get("budget") or 0)
    lc = st.get("local_constraint") or {}
    house_rule = constraint(lc, "house_rule", "house rule")
    room_type = constraint(lc, "room_type", "room type")
    cuisines = norm_list(constraint(lc, "cuisine", "cuisines"))
    transport_rule = (constraint(lc, "transportation") or "")
    transport_rule = transport_rule.lower() if isinstance(transport_rule, str) else \
        " ".join(norm_list(transport_rule)).lower()
    no_flight = "no flight" in transport_rule
    no_driving = "no self-driving" in transport_rule or "no self driving" in transport_rule

    try:
        start = date.fromisoformat(str(st["start_date"]).strip())
    except ValueError:
        fail(f"start_date must be YYYY-MM-DD, got {st['start_date']!r}")
    dates = [(start + timedelta(days=i)).isoformat() for i in range(days)]
    if days < 2:
        fail("Trips need at least 2 days (outbound and return).")
    nights = days - 1
    if n_cities > nights:
        fail(f"{n_cities} cities cannot fit in {nights} nights.")

    notes: list[str] = []
    city_states = db.load_city_states(data_dir)
    state_cities = db.cities_for_state(city_states, destination)
    if state_cities is not None:
        candidates = [c for c in state_cities if c.lower() != origin.lower()]
        dest_kind = "state"
    else:
        candidates = [destination]
        dest_kind = "city"
        if n_cities > 1:
            notes.append(f"Destination {destination!r} is a city, not a state; "
                         f"visiting it alone instead of {n_cities} cities.")
            n_cities = 1
        if db.state_of_city(city_states, destination) is None:
            notes.append(f"{destination!r} is not in the city list; lookups may be empty.")

    accs = db.load_accommodations(data_dir)
    rests = db.load_restaurants(data_dir)
    atts = db.load_attractions(data_dir)
    dists = db.load_distances(data_dir)
    all_cities = set(candidates) | {origin}
    flights = db.load_flights(data_dir, set(dates), all_cities)

    # Per-city resources.
    city_info: dict[str, dict] = {}
    for c in candidates:
        ca = [a for a in db.by_city(accs, c, "city") if accommodation_ok(a, room_type, house_rule)]
        for a in ca:
            a["_nightly"] = a["price"] * math.ceil(people / a["maximum occupancy"])
        ca.sort(key=lambda a: (a["_nightly"], -a["review rate number"]))
        cr = sorted(db.by_city(rests, c, "City"), key=lambda r: (r["Average Cost"], -r["Aggregate Rating"]))
        cat = db.by_city(atts, c, "City")
        city_info[c] = {"acc": ca, "rest": cr, "att": cat}

    # Transport options per (from, to, date) and regime.
    flight_index: dict[tuple, list] = {}
    for f in flights:
        flight_index.setdefault((f["OriginCityName"], f["DestCityName"], f["FlightDate"]), []).append(f)
    for v in flight_index.values():
        v.sort(key=lambda f: (f["Price"], f["DepTime"]))

    leg_cache: dict[tuple, dict | None] = {}

    def best_leg(a: str, b: str, d: str, regime: str) -> dict | None:
        key = (a, b, d, regime)
        if key in leg_cache:
            return leg_cache[key]
        opts = []
        if regime == "flight" and not no_flight:
            for f in flight_index.get((a, b, d), [])[:1]:
                opts.append({"mode": "flight", "cost": f["Price"] * people, "flight": f})
        if regime == "driving" and not no_driving:
            info = db.search_distance(dists, a, b, "self-driving")
            if info["valid"]:
                opts.append({"mode": "self-driving", "cost": info["cost"] * math.ceil(people / 5),
                             "info": info})
        info = db.search_distance(dists, a, b, "taxi")
        if info["valid"]:
            opts.append({"mode": "taxi", "cost": info["cost"] * math.ceil(people / 4), "info": info})
        best = min(opts, key=lambda o: o["cost"]) if opts else None
        leg_cache[key] = best
        return best

    def best_acc(c: str, n: int) -> dict | None:
        for a in city_info[c]["acc"]:
            if a["minimum nights"] <= n:
                return a
        return None

    # Rough meal estimate for ranking: 3 cheapest-per-slot restaurants per day in the city.
    def meal_estimate(c: str, n: int) -> float:
        costs = [r["Average Cost"] for r in city_info[c]["rest"][: 3 * (n + 1)]]
        return sum(costs) * people

    usable = [c for c in candidates if city_info[c]["acc"] and city_info[c]["rest"]]
    if len(usable) < n_cities:
        notes.append(f"Only {len(usable)} destination cities have both matching accommodations "
                     f"and restaurants; need {n_cities}.")

    options = []
    regimes = [r for r in ("flight", "driving") if not (r == "flight" and no_flight)
               and not (r == "driving" and no_driving)] or ["taxi-only"]
    for route in itertools.permutations(usable, n_cities):
        for split in compositions(nights, n_cities):
            accs_sel = []
            acc_cost = 0.0
            for c, n in zip(route, split):
                a = best_acc(c, n)
                if a is None:
                    break
                accs_sel.append(a)
                acc_cost += a["_nightly"] * n
            else:
                stops = [origin, *route, origin]
                tdays = [0]
                for n in split:
                    tdays.append(tdays[-1] + n)
                for regime in regimes:
                    legs = []
                    for i in range(len(stops) - 1):
                        leg = best_leg(stops[i], stops[i + 1], dates[tdays[i]], regime)
                        if leg is None:
                            break
                        legs.append(leg)
                    else:
                        tcost = sum(l["cost"] for l in legs)
                        mcost = sum(meal_estimate(c, n) for c, n in zip(route, split))
                        unevenness = max(split) - min(split)
                        options.append({"route": route, "split": split, "transfer_days": tdays,
                                        "legs": legs, "accs": accs_sel, "est_cost": tcost + acc_cost + mcost,
                                        "unevenness": unevenness, "regime": regime})
    if not options:
        fail("No feasible combination of route, transport and accommodation in the sandbox. "
             + " ".join(notes))

    def rank(o):
        over = budget > 0 and o["est_cost"] > budget
        return (over, o["unevenness"], o["est_cost"]) if not over else (over, 0, o["est_cost"])

    options.sort(key=rank)
    best = options[0]

    # ------------------------------------------------------- build the plan ---
    used_rest: set[str] = set()
    used_att: set[str] = set()
    route, split, tdays, legs = best["route"], best["split"], best["transfer_days"], best["legs"]
    stops = [origin, *route, origin]

    # Day -> where each slot happens.
    def leg_times(leg) -> tuple[int, int]:
        if leg["mode"] == "flight":
            dep = hhmm(leg["flight"]["DepTime"]) or 0
            arr = hhmm(leg["flight"]["ArrTime"]) or 0
            if arr < dep:
                arr += 1440
            return dep, arr
        return GROUND_DEPART, GROUND_DEPART + duration_minutes(leg["info"]["duration"])

    day_rows = []
    slot_needs = []  # (day_index, slot, city)
    for di in range(days):
        if di in tdays:
            k = tdays.index(di)
            a_city, b_city = stops[k], stops[k + 1]
            leg = legs[k]
            dep, arr = leg_times(leg)
            if leg["mode"] == "flight":
                f = leg["flight"]
                transport = (f"Flight Number: {f['Flight Number']}, from {a_city} to {b_city}, "
                             f"Departure Time: {f['DepTime']}, Arrival Time: {f['ArrTime']}")
            else:
                inf = leg["info"]
                label = "Self-driving" if leg["mode"] == "self-driving" else "Taxi"
                transport = (f"{label}, from {a_city} to {b_city}, duration: {inf['duration']}, "
                             f"distance: {inf['distance']}, cost: {inf['cost']}")
            row = {"days": di + 1, "current_city": f"from {a_city} to {b_city}",
                   "transportation": transport}
            for meal, t in MEALS.items():
                if dep >= t + 60 and a_city != origin:
                    slot_needs.append((di, meal, a_city))
                elif arr <= t - 30 and b_city != origin:
                    slot_needs.append((di, meal, b_city))
                else:
                    row[meal] = "-"
            if arr <= 16 * 60 and b_city != origin:
                slot_needs.append((di, "attraction1", b_city))
            elif dep >= 14 * 60 and a_city != origin:
                slot_needs.append((di, "attraction1", a_city))
            else:
                row["attraction"] = "-"
            stay = b_city if di < days - 1 else None
        else:
            # Find the city we're staying in.
            k = max(i for i, t in enumerate(tdays) if t < di)
            city = stops[k + 1]
            row = {"days": di + 1, "current_city": city, "transportation": "-"}
            for meal in MEALS:
                slot_needs.append((di, meal, city))
            slot_needs.append((di, "attraction1", city))
            slot_needs.append((di, "attraction2", city))
            stay = city
        if stay:
            a = best["accs"][route.index(stay)]
            row["accommodation"] = name_city(a["NAME"], stay)
        else:
            row["accommodation"] = "-"
        day_rows.append(row)

    # Restaurants: cover required cuisines first, then cheapest distinct per slot.
    meal_slots = [s for s in slot_needs if not s[1].startswith("attraction")]
    assigned: dict[tuple, dict] = {}
    uncovered = [c.lower() for c in cuisines]
    for cz in list(uncovered):
        if cz not in uncovered:
            continue
        best_pick = None
        for slot in meal_slots:
            if slot in assigned:
                continue
            for r in city_info[slot[2]]["rest"]:
                if r["Name"] in used_rest:
                    continue
                if cz in (x.lower() for x in r["cuisine_list"]):
                    covers = sum(1 for u in uncovered if u in (x.lower() for x in r["cuisine_list"]))
                    keyv = (-covers, r["Average Cost"])
                    if best_pick is None or keyv < best_pick[0]:
                        best_pick = (keyv, slot, r)
                    break
        if best_pick:
            _, slot, r = best_pick
            assigned[slot] = r
            used_rest.add(r["Name"])
            have = {x.lower() for x in r["cuisine_list"]}
            uncovered = [u for u in uncovered if u not in have]
    if uncovered:
        notes.append(f"Could not cover cuisines {uncovered} in the chosen cities.")
    for slot in meal_slots:
        if slot in assigned:
            continue
        for r in city_info[slot[2]]["rest"]:
            if r["Name"] not in used_rest:
                assigned[slot] = r
                used_rest.add(r["Name"])
                break
    att_assigned: dict[tuple, list] = {}
    for slot in [s for s in slot_needs if s[1].startswith("attraction")]:
        for a in city_info[slot[2]]["att"]:
            if a["Name"] not in used_att:
                used_att.add(a["Name"])
                att_assigned.setdefault((slot[0], slot[2]), []).append(a)
                break

    meal_cost = 0.0
    for (di, meal, city), r in assigned.items():
        day_rows[di][meal] = name_city(r["Name"], city)
        meal_cost += r["Average Cost"] * people
    for row in day_rows:
        di = row["days"] - 1
        for meal in MEALS:
            row.setdefault(meal, "-")
        if "attraction" not in row:
            picks = [name_city(a["Name"], c) for (d, c), lst in att_assigned.items() if d == di for a in lst]
            row["attraction"] = ";".join(picks) + ";" if picks else "-"
    order = ["days", "current_city", "transportation", "breakfast", "attraction", "lunch",
             "dinner", "accommodation"]
    day_rows = [{k: r[k] for k in order} for r in day_rows]

    transport_cost = sum(l["cost"] for l in legs)
    acc_cost = sum(a["_nightly"] * n for a, n in zip(best["accs"], split))
    total = round(transport_cost + acc_cost + meal_cost, 2)
    if budget and total > budget:
        notes.append(f"Draft costs {total} which exceeds the budget {budget}; "
                     "this is the cheapest feasible option found.")

    # ------------------------------------------------ candidates for edits ---
    cand_out = {}
    for c in route:
        info = city_info[c]
        n = split[route.index(c)]
        cz_l = [x.lower() for x in cuisines]
        cand_out[c] = {
            "nights": n,
            "accommodations": [{"name": a["NAME"], "room_type": a["room type"], "price": a["price"],
                                "nightly_cost_for_party": a["_nightly"],
                                "minimum_nights": a["minimum nights"],
                                "maximum_occupancy": a["maximum occupancy"],
                                "house_rules": a["house_rules"], "rating": a["review rate number"]}
                               for a in info["acc"] if a["minimum nights"] <= n][:8],
            "restaurants": [{"name": r["Name"], "cost": r["Average Cost"], "cuisines": r["Cuisines"],
                             "rating": r["Aggregate Rating"]}
                            for r in info["rest"]
                            if len(cz_l) == 0 or True][:15],
            "restaurants_matching_cuisines": [
                {"name": r["Name"], "cost": r["Average Cost"], "cuisines": r["Cuisines"]}
                for r in info["rest"] if any(x.lower() in cz_l for x in r["cuisine_list"])][:10],
            "attractions": [a["Name"] for a in info["att"]][:20],
        }
    alts = [{"route": list(o["route"]), "nights": list(o["split"]), "regime": o["regime"],
             "estimated_cost": round(o["est_cost"], 2)} for o in options[1:6]]

    print(json.dumps({
        "feasible": True,
        "data_dir": str(data_dir),
        "destination_kind": dest_kind,
        "trip_dates": dates,
        "candidate_cities": candidates,
        "route": {"cities": list(route), "nights": list(split), "regime": best["regime"],
                  "legs": [{"from": stops[i], "to": stops[i + 1], "date": dates[tdays[i]],
                            "mode": l["mode"], "cost": l["cost"]} for i, l in enumerate(legs)]},
        "draft_plan": day_rows,
        "draft_cost": total,
        "cost_breakdown": {"transportation": round(transport_cost, 2),
                           "accommodation": round(acc_cost, 2),
                           "meals": round(meal_cost, 2), "attractions": 0},
        "alternatives": alts,
