                                        "missing_cz": missing_cz})""")
s=s.replace("""        return (over, o["unevenness"], o["est_cost"]) if not over else (over, 0, o["est_cost"])""","""        # Cuisine coverage first, then budget, then the most even split, then cost.
        if over:
            return (o["missing_cz"], over, 0, o["est_cost"])
        return (o["missing_cz"], over, o["unevenness"], o["est_cost"])""")
open(p,'w').write(s)
