    used_rest: list[str] = []
    used_att: list[str] = []
    modes: set[str] = set()
    sequence: list[str] = []  # cities in visiting order, consecutive duplicates collapsed
    acc_runs: list[list] = []  # [name_city, count, row]
    dest_rest_cuisines: set[str] = set()

